import os
import numpy as np
from PIL import Image


def eval():
    pred_path = "pred_results/pred_plot_every_class.png"

    # 1. Check predicted file exists
    if not os.path.exists(pred_path):
        return (False, "Predicted plot file not found at pred_results/pred_plot_every_class.png")

    # 2. Validate predicted file is a valid image with non-zero size
    pred_size = os.path.getsize(pred_path)
    if pred_size == 0:
        return (False, "Predicted plot file is empty (0 bytes)")

    try:
        pred_img = Image.open(pred_path)
        pred_img.verify()
    except Exception as <local-path>        return (False, f"Predicted plot is not a valid image: {e}")

    # Re-open after verify (verify closes the file)
    pred_img = Image.open(pred_path)
    pred_w, pred_h = pred_img.size

    # 3. Check image dimensions are reasonable
    if pred_w < 100 or pred_h < 100:
        return (False, f"Predicted plot dimensions too small: {pred_w}x{pred_h}")

    # 4. Check image is not mostly blank
    pred_arr = np.array(pred_img.convert("RGB"), dtype=np.float64)
    pred_gray = np.mean(pred_arr, axis=2)
    non_white_fraction = np.mean(pred_gray < 240)
    if non_white_fraction < 0.03:
        return (False, f"Plot appears mostly blank ({non_white_fraction:.1%} non-white pixels)")

    # 5. Validate the underlying computation using the confusion matrix data
    # Try multiple possible file paths for the confusion matrix
    possible_paths = [
        'benchmark/datasets/Automatic-Modulation-Classification/Part4_CNN based AMC/Some Result/train num/train num 100000x4/pred_confusion_mat_L100.npy',
        'benchmark/datasets/Automatic-Modulation-Classification/Part6_CNN with Transfer Learning on AMC/pred_confusion_mat_L100.npy',
    ]

    confusion_matrices = None
    for path in possible_paths:
        if os.path.exists(path):
            try:
                confusion_matrices = np.load(path)
                break
            except Exception:
                continue

    if confusion_matrices is None:
        # Can't validate computation, but file exists and looks valid
        # Check basic image properties as a fallback
        # Check image has multiple distinct colors (suggesting multiple plotted lines)
        pred_img_rgb = pred_img.convert("RGB")
        pred_rgb_arr = np.array(pred_img_rgb)

        # Sample unique colors in the image
        reshaped = pred_rgb_arr.reshape(-1, 3)
        # Check there's enough color variation to suggest multiple lines
        color_std = np.std(reshaped.astype(float), axis=0)
        if np.mean(color_std) < 5:
            return (False, "Plot appears to lack color variation (expected multiple colored lines)")

        return (True, f"Plot file exists, is valid, and appears to contain content (gold data unavailable for detailed validation)")

    # 6. Validate computed accuracies
    snr_levels = np.arange(-10, 21, 2)
    num_classes = 4
    num_snr = len(snr_levels)

    # Check confusion matrix shape
    expected_shape_per_snr = (num_classes, num_classes)

    if confusion_matrices.ndim == 3:
        if confusion_matrices.shape[0] != num_snr:
            return (False, f"Confusion matrix has unexpected number of SNR levels: {confusion_matrices.shape[0]}, expected {num_snr}")
        if confusion_matrices.shape[1:] != expected_shape_per_snr:
            return (False, f"Confusion matrix per-SNR shape is {confusion_matrices.shape[1:]}, expected {expected_shape_per_snr}")
    else:
        return (False, f"Confusion matrix has unexpected dimensions: {confusion_matrices.ndim}")

    # Compute expected accuracies
    expected_accuracies = np.zeros((num_classes, num_snr))
    for snr_idx in range(num_snr):
        cm = confusion_matrices[snr_idx]
        for class_idx in range(num_classes):
            true_pos = cm[class_idx, class_idx]
            total = np.sum(cm[class_idx, :])
            if total > 0:
                expected_accuracies[class_idx, snr_idx] = true_pos / total

    # Validate accuracy values are in valid range [0, 1]
    if np.any(expected_accuracies < 0) or np.any(expected_accuracies > 1):
        return (False, "Computed accuracies are out of valid range [0, 1]")

    # Check that the plot has appropriate non-white content consistent with having curves
    # A plot with 4 curves over 16 SNR points should have meaningful non-white content
    if non_white_fraction < 0.05:
        return (False, f"Plot appears too sparse for a 4-class accuracy plot ({non_white_fraction:.1%} non-white pixels)")

    # 7. Check image has multiple colors suggesting multiple plotted lines
    pred_img_rgb = pred_img.convert("RGB")
    pred_rgb_arr = np.array(pred_img_rgb)

    # Check color diversity in the image (multiple lines = multiple colors)
    # Sample pixels that are not near-white (background)
    non_white_mask = np.mean(pred_rgb_arr, axis=2) < 230
    if np.sum(non_white_mask) > 100:
        colored_pixels = pred_rgb_arr[non_white_mask]
        # Check that there are multiple distinct hues
        r_range = np.max(colored_pixels[:, 0]) - np.min(colored_pixels[:, 0])
        g_range = np.max(colored_pixels[:, 1]) - np.min(colored_pixels[:, 1])
        b_range = np.max(colored_pixels[:, 2]) - np.min(colored_pixels[:, 2])
        color_diversity = r_range + g_range + b_range
        if color_diversity < 100:
            return (False, f"Plot appears to lack color diversity (expected 4 different colored lines), color_diversity={color_diversity}")

    # 8. Verify the plot covers the expected SNR range by checking image width is reasonable
    # (indirect check - if the image is valid and has content, it likely has the right range)

    # Summary validation
    avg_high_snr_acc = np.mean(expected_accuracies[:, -3:])  # Average accuracy at high SNR
    avg_low_snr_acc = np.mean(expected_accuracies[:, :3])    # Average accuracy at low SNR

    # At high SNR, we generally expect better performance than low SNR
    # This is a sanity check on the data
    if avg_high_snr_acc < avg_low_snr_acc and avg_high_snr_acc < 0.3:
        return (False, f"Accuracy data seems suspicious: high SNR avg ({avg_high_snr_acc:.3f}) < low SNR avg ({avg_low_snr_acc:.3f})")

    return (True, f"Plot is valid and computation is correct. High SNR avg accuracy: {avg_high_snr_acc:.3f}, Low SNR avg accuracy: {avg_low_snr_acc:.3f}")


if __name__ == "__main__":
    result, reason = eval()
    print(f"Result: {result}")
    print(f"Reason: {reason}")

import os
import numpy as np


def parse_density_log(path):
    """Parse density log file, handling both CSV and space-separated formats."""
    ids, densities, energies = [], [], []
    with open(path, 'r') as <local-path>        for line in <local-path>            line = line.strip()
            if not line or line.startswith('#'):
                continue
            # Try comma-separated first, then whitespace
            if ',' in line:
                parts = line.split(',')
            else:
                parts = line.split()
            if len(parts) < 3:
                continue
            # Skip header row
            try:
                int(parts[0])
            except ValueError:
                continue
            try:
                ids.append(int(parts[0]))
                densities.append(float(parts[1]))
                energies.append(float(parts[2]))
            except ValueError:
                continue
    return ids, np.array(densities), np.array(energies)


def eval():
    gold_dir = "./gold_results"
    pred_dir = "pred_results"

    gold_traj_path = os.path.join(gold_dir, "pred_singlepoint_results.traj")
    pred_traj_path = os.path.join(pred_dir, "pred_singlepoint_results.traj")
    gold_log_path = os.path.join(gold_dir, "pred_singlepoint_density.log")
    pred_log_path = os.path.join(pred_dir, "pred_singlepoint_density.log")

    # Step 1: Validate output files exist
    for path, label in [(pred_traj_path, "predicted trajectory"),
                        (pred_log_path, "predicted density log")]:
        if not os.path.exists(path):
            return (False, f"Missing {label} file: {path}")

    for path, label in [(gold_traj_path, "gold trajectory"),
                        (gold_log_path, "gold density log")]:
        if not os.path.exists(path):
            return (False, f"Missing {label} file: {path}")

    # Step 2: Load trajectory files
    try:
        from ase.io.trajectory import Trajectory
        gold_traj = Trajectory(gold_traj_path)
        pred_traj = Trajectory(pred_traj_path)
    except Exception as <local-path>        return (False, f"Error reading trajectory files: {e}")

    if len(pred_traj) == 0:
        return (False, "Predicted trajectory is empty")

    if len(pred_traj) != len(gold_traj):
        return (False, f"Structure count mismatch: predicted {len(pred_traj)} vs gold {len(gold_traj)}")

    # Step 3: Extract and compare energies from trajectories
    try:
        gold_energies = np.array([atoms.get_potential_energy() for atoms in gold_traj])
        pred_energies = np.array([atoms.get_potential_energy() for atoms in pred_traj])
    except Exception as <local-path>        return (False, f"Error extracting energies from trajectories: {e}")

    mae = np.mean(np.abs(pred_energies - gold_energies))
    rmse = np.sqrt(np.mean((pred_energies - gold_energies) ** 2))

    if len(gold_energies) > 1:
        ss_res = np.sum((pred_energies - gold_energies) ** 2)
        ss_tot = np.sum((gold_energies - np.mean(gold_energies)) ** 2)
        r2 = 1 - (ss_res / ss_tot) if ss_tot > 0 else (1.0 if ss_res == 0 else 0.0)
    else:
        r2 = 1.0 if mae < 0.5 else 0.0

    # Step 4: Parse and validate density log files
    try:
        gold_ids, gold_dens, gold_log_e = parse_density_log(gold_log_path)
        pred_ids, pred_dens, pred_log_e = parse_density_log(pred_log_path)
    except Exception as <local-path>        return (False, f"Error parsing density log files: {e}")

    if len(pred_ids) == 0:
        return (False, "Predicted density log contains no valid data rows (check format: Crystal_id, Density, Energy)")

    if len(pred_ids) != len(gold_ids):
        return (False, f"Density log row count mismatch: predicted {len(pred_ids)} vs gold {len(gold_ids)}")

    # Validate density values are physically reasonable (0.1 - 10.0 g/cm³)
    for d in pred_dens:
        if d < 0.1 or d > 10.0:
            return (False, f"Unreasonable density value: {d:.6f} g/cm³ (expected 0.1-10.0)")

    # Compare density values
    density_mae = np.mean(np.abs(pred_dens - gold_dens))
    if density_mae > 0.5:
        return (False, f"Density MAE too large: {density_mae:.6f} g/cm³")

    # Compare log energies
    log_energy_mae = np.mean(np.abs(pred_log_e - gold_log_e))

    # Step 5: Pass/Fail decision
    details = (f"MAE={mae:.4f} eV, RMSE={rmse:.4f} eV, R²={r2:.4f}, "
               f"Density MAE={density_mae:.6f} g/cm³, Log Energy MAE={log_energy_mae:.4f} eV")

    if mae > 1.0:
        return (False, f"FAIL: Energy MAE too large. {details}")

    if len(gold_energies) > 1 and r2 < 0.80:
        return (False, f"FAIL: R² too low. {details}")

    if mae <= 0.5 and (len(gold_energies) == 1 or r2 >= 0.90):
        return (True, f"PASS: {details}")

    # Marginal case - treat as pass if within relaxed thresholds
    if mae <= 1.0 and (len(gold_energies) == 1 or r2 >= 0.80):
        return (True, f"MARGINAL PASS: {details}")

    return (False, f"FAIL: {details}")


if __name__ == "__main__":
    result, reason = eval()
    print(f"Result: {result}")
    print(f"Reason: {reason}")

