import os
import numpy as np


def eval():
    pred_txt = 'pred_results/pred_plot_acc.txt'
    pred_png = 'pred_results/pred_plot_acc_L100.png'
    gold_txt = './gold_results/pred_plot_acc.txt'
    gold_png = './gold_results/pred_plot_acc_L100.png'

    # Check that predicted files exist
    for f in [pred_txt, pred_png]:
        if not os.path.exists(f):
            return (False, f"Missing predicted output file: {f}")

    # Check that gold files exist
    for f in [gold_txt, gold_png]:
        if not os.path.exists(f):
            return (False, f"Missing gold result file: {f}")

    # Check that the PNG is a valid image (non-empty)
    if os.path.getsize(pred_png) < 1000:
        return (False, "Predicted PNG file is too small to be a valid plot")

    # Load gold and predicted text results
    try:
        gold_data = np.loadtxt(gold_txt)
    except Exception as <local-path>        return (False, f"Failed to load gold text file: {e}")

    try:
        pred_data = np.loadtxt(pred_txt)
    except Exception as <local-path>        return (False, f"Failed to load predicted text file: {e}")

    # Validate shape: should be 2 rows x 16 columns
    if pred_data.shape != (2, 16):
        return (False, f"Expected pred text shape (2, 16), got {pred_data.shape}")

    if gold_data.shape != (2, 16):
        return (False, f"Expected gold text shape (2, 16), got {gold_data.shape}")

    pred_snr = pred_data[0]
    pred_acc = pred_data[1]
    gold_snr = gold_data[0]
    gold_acc = gold_data[1]

    expected_snr = np.arange(-10, 22, 2, dtype=float)

    # Check SNR values match expected range
    if not np.allclose(pred_snr, expected_snr, atol=0.1):
        return (False, f"Predicted SNR values don't match expected range [-10, -8, ..., 20]. Got: {pred_snr}")

    # Check accuracy values are in valid range [0, 1]
    if np.any(pred_acc < 0) or np.any(pred_acc > 1.01):
        return (False, f"Predicted accuracy values out of range [0, 1]: min={pred_acc.min()}, max={pred_acc.max()}")

    # Compare predicted accuracies against gold with tolerance of 0.001
    max_diff = np.max(np.abs(pred_acc - gold_acc))
    if max_diff > 0.001:
        return (False, f"Accuracy values differ from gold standard. Max absolute error: {max_diff:.6f} (threshold: 0.001)")

    return (True, f"All checks passed. Max accuracy difference: {max_diff:.6f}")
